-- Darkmoon Faire event 75 spawns and carousel baseline.
-- Adds event-owned Darkmoon Faire content across maps 0, 1, 530, 571, and 974.
-- Existing unlinked matching spawns are linked to event 75; overlaps owned by other events are inserted with new GUIDs.

SET @DARKMOON_EVENT_ENTRY := 75;
SET @DARKMOON_CREATURE_GUID_START := 8200000;
SET @DARKMOON_CREATURE_GUID_COUNT := 296;
SET @DARKMOON_GAMEOBJECT_GUID_START := 901000;
SET @DARKMOON_GAMEOBJECT_GUID_COUNT := 347;
SET @CAROUSEL_GAMEOBJECT_GUID_START := 900200;
SET @CAROUSEL_GAMEOBJECT_GUID_COUNT := 2;

CREATE TABLE IF NOT EXISTS `transport_legacy` (
  `entry` int(10) unsigned NOT NULL,
  `transport_entry` int(10) unsigned NOT NULL,
  `map` smallint(5) unsigned NOT NULL,
  `spawnMask` int(10) unsigned NOT NULL DEFAULT '1',
  `flags` int(10) unsigned NOT NULL DEFAULT '0',
  `comment` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`entry`, `map`, `spawnMask`),
  KEY `idx_transport_entry` (`transport_entry`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='Legacy GAMEOBJECT_TYPE_TRANSPORT local transport compatibility';

START TRANSACTION;

-- Darkmoon Faire now follows the MoP Classic two-week cadence: one week active, one week inactive.
INSERT INTO `game_event` (`eventEntry`, `start_time`, `end_time`, `occurence`, `length`, `holiday`, `description`, `world_event`, `announce`) VALUES
(@DARKMOON_EVENT_ENTRY, '2026-07-26 02:01:00', '2030-12-31 09:59:00', 20160, 10080, 479, 'Darkmoon Faire', 0, 2)
ON DUPLICATE KEY UPDATE
    `start_time` = VALUES(`start_time`),
    `end_time` = VALUES(`end_time`),
    `occurence` = VALUES(`occurence`),
    `length` = VALUES(`length`),
    `holiday` = VALUES(`holiday`),
    `description` = VALUES(`description`),
    `world_event` = VALUES(`world_event`),
    `announce` = VALUES(`announce`);

-- Clear only the GUID ranges reserved by this update so the script can be reapplied.
DELETE FROM `creature_addon` WHERE `guid` BETWEEN @DARKMOON_CREATURE_GUID_START AND (@DARKMOON_CREATURE_GUID_START + @DARKMOON_CREATURE_GUID_COUNT - 1);
DELETE FROM `game_event_creature` WHERE `guid` BETWEEN @DARKMOON_CREATURE_GUID_START AND (@DARKMOON_CREATURE_GUID_START + @DARKMOON_CREATURE_GUID_COUNT - 1);
DELETE FROM `creature` WHERE `guid` BETWEEN @DARKMOON_CREATURE_GUID_START AND (@DARKMOON_CREATURE_GUID_START + @DARKMOON_CREATURE_GUID_COUNT - 1);
DELETE FROM `game_event_gameobject` WHERE `guid` BETWEEN @DARKMOON_GAMEOBJECT_GUID_START AND (@DARKMOON_GAMEOBJECT_GUID_START + @DARKMOON_GAMEOBJECT_GUID_COUNT - 1);
DELETE FROM `gameobject` WHERE `guid` BETWEEN @DARKMOON_GAMEOBJECT_GUID_START AND (@DARKMOON_GAMEOBJECT_GUID_START + @DARKMOON_GAMEOBJECT_GUID_COUNT - 1);
DELETE FROM `game_event_gameobject` WHERE `guid` = 72057;
DELETE FROM `gameobject` WHERE `guid` = 72057;

-- Replace waypoint paths used by the Darkmoon Faire creatures.
DELETE FROM `waypoint_data` WHERE `id` IN (
303587, 303589, 303591, 303593, 303594, 303595, 303596, 303597, 303611, 303612, 303613, 303614, 303615, 303616, 303617, 303618, 303619, 303620, 303636, 303637, 303646, 303648, 303649, 303650, 303666, 303678, 303680, 303683, 303684, 303721, 303731, 303733, 303735, 303736, 303742, 303743, 303746, 303747, 303755, 303764, 303772, 303782, 303786, 303791, 303804, 303807, 303808, 303809, 303812, 303813, 303817, 303820, 303822, 303824, 303825, 303831, 303833, 303836, 303840, 303841, 303847, 303848, 303850, 303853, 303855, 303856, 303857, 303872, 303873, 303902, 303907, 303910, 303911, 303912, 303940, 303946, 303951, 303954, 303959, 303960, 303968, 303991, 303998, 304003, 304004, 304005, 304006, 304007, 304009, 304010, 304122, 308482, 311382, 315791, 315792, 315793, 316891, 318143, 318144, 318309, 358593, 375540, 375550, 375551);

-- Replace placeholder carousel templates and spawns with the island carousel data.
DELETE FROM `game_event_gameobject`
WHERE `guid` IN (SELECT `guid` FROM `gameobject` WHERE `id` IN (216627, 216666))
   OR `guid` BETWEEN @CAROUSEL_GAMEOBJECT_GUID_START AND (@CAROUSEL_GAMEOBJECT_GUID_START + @CAROUSEL_GAMEOBJECT_GUID_COUNT - 1);
DELETE FROM `gameobject`
WHERE `id` IN (216627, 216666)
   OR `guid` BETWEEN @CAROUSEL_GAMEOBJECT_GUID_START AND (@CAROUSEL_GAMEOBJECT_GUID_START + @CAROUSEL_GAMEOBJECT_GUID_COUNT - 1);
DELETE FROM `gameobject_template` WHERE `entry` IN (216627, 216666);
DELETE FROM `npc_spellclick_spells` WHERE `npc_entry` IN (68231, 68232, 68233, 68238, 68239);
DELETE FROM `creature_template` WHERE `entry` IN (68231, 68232, 68233, 68238, 68239);
DELETE FROM `transport_legacy` WHERE `entry` IN (216666);

